def pluck(arr):
    best_value = None
    best_index = -1
    for i, v in enumerate(arr):
        if v % 2 == 0 and (best_value is None or v < best_value):
            best_value = v
            best_index = i
    if best_value is None:
        return []
    return [best_value, best_index]
